export function summary(user) {
  return { name: user.name, displayName: user.name.toUpperCase() };
}

import test from "node:test";
import assert from "node:assert/strict";
import { summary } from "../lib/summary.mjs";

test("summary has name and displayName", () => {
  assert.deepEqual(summary({ name: "ada" }), { name: "ada", displayName: "ADA" });
});

test("name field kept for compatibility", () => {
  assert.equal(summary({ name: "ada" }).name, "ada");
});
